-- V2-M3.3 QR Tagging.
--
-- A runner's screen shows a signed code that changes every 20 s. A hunter scans
-- it and tag_by_qr verifies the signature, the expiry, the hunter's team and the
-- live phase before applying the same tag as the GPS button.
--
-- The signing key is generated by this migration into a deny-all table and is
-- only ever read inside SECURITY DEFINER functions. It is never selected by a
-- client and never stored in the repository. Rotating it invalidates every
-- outstanding code (delete the row; the next call generates a new one? no: we
-- generate on read if missing, which is safe because the table is server-only).
--
-- C-11: storage choice is the deny-all table, not Supabase Vault.

create extension if not exists pgcrypto with schema extensions;

create table public.server_secrets (
  key text primary key,
  value text not null,
  created_at timestamptz not null default now()
);

alter table public.server_secrets enable row level security;
revoke all on public.server_secrets from anon, authenticated;

insert into public.server_secrets (key, value)
values ('qr_hmac', encode(gen_random_bytes(32), 'hex'))
on conflict (key) do nothing;

-- One row per scanned code. The unique hash is what makes a token one-time.
create table public.qr_uses (
  id bigint generated always as identity primary key,
  token_hash text not null unique,
  game_id uuid not null references public.games(id) on delete cascade,
  runner_id uuid not null references public.players(id) on delete cascade,
  hunter_id uuid not null references public.players(id) on delete cascade,
  used_at timestamptz not null default now()
);

alter table public.qr_uses enable row level security;
revoke all on public.qr_uses from anon, authenticated;

create or replace function public.qr_secret()
returns text
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  secret text;
begin
  select value into secret from public.server_secrets where key = 'qr_hmac';
  if secret is null then
    insert into public.server_secrets (key, value)
    values ('qr_hmac', encode(gen_random_bytes(32), 'hex'))
    on conflict (key) do nothing;
    select value into secret from public.server_secrets where key = 'qr_hmac';
  end if;
  return secret;
end;
$$;

revoke all on function public.qr_secret() from public, anon, authenticated;

-- apply_tag -------------------------------------------------------------------
-- The one place a tag is applied. Shared by attempt_tag and tag_by_qr so the
-- two paths cannot drift (marking, event, last-runner ending).
create or replace function public.apply_tag(
  p_game_id uuid,
  p_hunter_id uuid,
  p_runner_id uuid,
  p_distance_m double precision
)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  current_game public.games%rowtype;
  target_runner public.players%rowtype;
  runner_name text;
  active_runners integer;
begin
  select * into current_game from public.games g where g.id = p_game_id for update;
  if not found then raise exception 'Game not found.'; end if;
  if current_game.status <> 'live' then
    raise exception 'Tagging is only available while the round is live.';
  end if;

  select * into target_runner from public.players p
    where p.id = p_runner_id and p.game_id = p_game_id
      and p.team = 'runner' and p.status = 'active'
    for update;
  if not found then raise exception 'That runner is not taggable.'; end if;

  select pr.display_name into runner_name
    from public.profiles pr where pr.id = target_runner.user_id;

  insert into public.tags (game_id, hunter_id, runner_id, distance_m)
  values (p_game_id, p_hunter_id, target_runner.id, greatest(0, p_distance_m)::real);

  update public.players p
    set status = 'tagged', tagged_at = now(), is_ready = false
    where p.id = target_runner.id;
  update public.players p set last_tag_attempt_at = null where p.id = p_hunter_id;

  insert into public.events (game_id, type, audience, payload)
  values (
    p_game_id, 'runner_tagged', 'all',
    jsonb_build_object(
      'runner_id', target_runner.id,
      'hunter_id', p_hunter_id,
      'display_name', runner_name
    )
  );

  select count(*) into active_runners
    from public.players p
    where p.game_id = p_game_id and p.team = 'runner' and p.status = 'active';

  if active_runners = 0 then
    perform public.end_game(p_game_id, 'hunters', 'all_tagged');
  end if;

  select * into current_game from public.games g where g.id = p_game_id;

  return jsonb_build_object(
    'success', true,
    'runner_id', target_runner.id,
    'phase', current_game.status,
    'winner', current_game.winner,
    'end_reason', current_game.end_reason
  );
end;
$$;

revoke all on function public.apply_tag(uuid, uuid, uuid, double precision)
  from public, anon, authenticated;

-- attempt_tag: same rules as v1, now delegating the tag itself.
create or replace function public.attempt_tag(game_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  caller_id uuid := auth.uid();
  current_game public.games%rowtype;
  me public.players%rowtype;
  my_pos public.player_positions%rowtype;
  target_id uuid;
  target_distance double precision;
begin
  if caller_id is null then raise exception 'Authentication is required.'; end if;

  select * into me from public.players p
    where p.game_id = attempt_tag.game_id
      and p.user_id = caller_id
      and p.status <> 'left'
    for update;
  if not found then raise exception 'You are not a player in this game.'; end if;
  if me.team <> 'hunter' then raise exception 'Only hunters can tag runners.'; end if;

  perform public.advance_game(attempt_tag.game_id);

  select * into current_game from public.games g
    where g.id = attempt_tag.game_id
    for update;
  if not found then raise exception 'Game not found.'; end if;
  if current_game.status <> 'live' then
    raise exception 'Tagging is only available while the round is live.';
  end if;

  if me.last_tag_attempt_at is not null
     and now() - me.last_tag_attempt_at < interval '8 seconds' then
    return jsonb_build_object('success', false, 'reason', 'cooldown');
  end if;

  select * into my_pos from public.player_positions pp where pp.player_id = me.id;
  if not found or now() - my_pos.recorded_at > interval '20 seconds' then
    return jsonb_build_object('success', false, 'reason', 'stale_position');
  end if;

  select p.id, extensions.st_distance(pp.geog, my_pos.geog)
    into target_id, target_distance
  from public.players p
  join public.player_positions pp on pp.player_id = p.id
  where p.game_id = current_game.id
    and p.team = 'runner'
    and p.status = 'active'
    and pp.recorded_at > now() - interval '20 seconds'
    and extensions.st_distance(pp.geog, my_pos.geog)
        <= current_game.tag_radius_m + least(
             10::double precision,
             (coalesce(my_pos.accuracy_m, 0)::double precision
              + coalesce(pp.accuracy_m, 0)::double precision) / 2
           )
  order by extensions.st_distance(pp.geog, my_pos.geog) asc
  limit 1;

  if target_id is null then
    update public.players p set last_tag_attempt_at = now() where p.id = me.id;
    return jsonb_build_object('success', false, 'reason', 'no_target');
  end if;

  return public.apply_tag(current_game.id, me.id, target_id, target_distance);
end;
$$;

revoke all on function public.attempt_tag(uuid) from public, anon;
grant execute on function public.attempt_tag(uuid) to authenticated;

-- qr_token -------------------------------------------------------------------
create or replace function public.qr_token(game_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  caller_id uuid := auth.uid();
  current_game public.games%rowtype;
  me public.players%rowtype;
  ttl_s integer;
  expires_epoch bigint;
  payload text;
  signature text;
begin
  if caller_id is null then raise exception 'Authentication is required.'; end if;

  select * into current_game from public.games g where g.id = qr_token.game_id;
  if not found then raise exception 'Game not found.'; end if;
  if current_game.status <> 'live' then
    raise exception 'QR codes are only available while the round is live.';
  end if;
  if not ('qr_tagging' = any(current_game.modifiers)) then
    raise exception 'This round does not use QR tagging.';
  end if;

  select * into me from public.players p
    where p.game_id = qr_token.game_id and p.user_id = caller_id and p.status <> 'left';
  if not found then raise exception 'You are not a player in this game.'; end if;
  if me.status <> 'active' then raise exception 'Tagged players do not show a code.'; end if;

  ttl_s := least(
    60,
    greatest(
      10,
      coalesce((current_game.mode_params->'qr_tagging'->>'token_ttl_s')::integer, 20)
    )
  );
  expires_epoch := floor(extract(epoch from now()))::bigint + ttl_s;
  payload := current_game.id::text || '|' || me.id::text || '|' || expires_epoch::text;
  signature := encode(hmac(payload, public.qr_secret(), 'sha256'), 'hex');

  return jsonb_build_object(
    'token', me.id::text || '.' || expires_epoch::text || '.' || signature,
    'expires_at', to_timestamp(expires_epoch),
    'ttl_s', ttl_s,
    'player_id', me.id,
    'team', me.team
  );
end;
$$;

revoke all on function public.qr_token(uuid) from public, anon;
grant execute on function public.qr_token(uuid) to authenticated;

-- tag_by_qr ------------------------------------------------------------------
create or replace function public.tag_by_qr(game_id uuid, token text)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  caller_id uuid := auth.uid();
  current_game public.games%rowtype;
  me public.players%rowtype;
  my_pos public.player_positions%rowtype;
  parts text[];
  runner_id uuid;
  expires_epoch bigint;
  expected text;
  runner_pos public.player_positions%rowtype;
  distance_m double precision := 0;
begin
  if caller_id is null then raise exception 'Authentication is required.'; end if;
  if token is null or length(trim(token)) = 0 then raise exception 'Scan a code first.'; end if;

  select * into me from public.players p
    where p.game_id = tag_by_qr.game_id
      and p.user_id = caller_id
      and p.status <> 'left'
    for update;
  if not found then raise exception 'You are not a player in this game.'; end if;
  if me.team <> 'hunter' then raise exception 'Only hunters can scan a runner code.'; end if;

  perform public.advance_game(tag_by_qr.game_id);

  select * into current_game from public.games g
    where g.id = tag_by_qr.game_id
    for update;
  if not found then raise exception 'Game not found.'; end if;
  if current_game.status <> 'live' then
    raise exception 'Tagging is only available while the round is live.';
  end if;
  if not ('qr_tagging' = any(current_game.modifiers)) then
    raise exception 'This round does not use QR tagging.';
  end if;

  parts := string_to_array(trim(token), '.');
  if array_length(parts, 1) <> 3 then raise exception 'That code is not valid.'; end if;

  begin
    runner_id := parts[1]::uuid;
    expires_epoch := parts[2]::bigint;
  exception
    when others then raise exception 'That code is not valid.';
  end;

  if expires_epoch < floor(extract(epoch from now())) then
    raise exception 'That code has expired. Ask for a fresh one.';
  end if;
  if expires_epoch > floor(extract(epoch from now())) + 120 then
    raise exception 'That code is not valid.';
  end if;

  expected := encode(
    hmac(
      current_game.id::text || '|' || runner_id::text || '|' || expires_epoch::text,
      public.qr_secret(),
      'sha256'
    ),
    'hex'
  );
  if expected <> lower(parts[3]) then
    raise exception 'That code is not valid.';
  end if;

  if not exists (
    select 1 from public.players p
    where p.id = runner_id and p.game_id = current_game.id
      and p.team = 'runner' and p.status = 'active'
  ) then
    raise exception 'That runner is no longer taggable.';
  end if;

  begin
    insert into public.qr_uses (token_hash, game_id, runner_id, hunter_id)
    values (encode(digest(trim(token), 'sha256'), 'hex'), current_game.id, runner_id, me.id);
  exception
    when unique_violation then
      raise exception 'That code has already been scanned. Ask for a fresh one.';
  end;

  -- Physical presence is the point of QR; keep the recorded distance honest when
  -- both fixes are fresh, otherwise record zero.
  select * into my_pos from public.player_positions pp where pp.player_id = me.id;
  select * into runner_pos from public.player_positions pp where pp.player_id = runner_id;
  if my_pos.geog is not null and runner_pos.geog is not null
     and now() - my_pos.recorded_at <= interval '30 seconds'
     and now() - runner_pos.recorded_at <= interval '30 seconds' then
    distance_m := extensions.st_distance(my_pos.geog, runner_pos.geog);
  end if;

  update public.players p set last_tag_attempt_at = null where p.id = me.id;
  return public.apply_tag(current_game.id, me.id, runner_id, distance_m);
end;
$$;

revoke all on function public.tag_by_qr(uuid, text) from public, anon;
grant execute on function public.tag_by_qr(uuid, text) to authenticated;
